head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf30000";
scwin.header_cd = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_searchStripBndListReq').set('pageIndex', "1");
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $('#paging7 table:first-child').attr('align', 'center');

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf30000.onpageload' }); }
};

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 3개다(strip#searchstripbndlist vs strip#searchbndspecbynew vs strip#searchbndspecbyaddmerge) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.header_cd =$c.util.getComponent('ipt_bndMktactTpCd').getValue(); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf30000' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf30000.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_searchStripBndList_onclick
 * @description btn_searchStripBndList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchStripBndList_onclick = async function(e){
    try {
        await scwin.searchStripBndList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf30000.btn_searchStripBndList_onclick' }); }
};

/**
 * @method
 * @name ipt_isuNm_onkeydown
 * @description ipt_isuNm 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_isuNm_onkeydown = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        if(event.keyCode===13){$c.str.replaceAll(selfVar);await scwin.searchStripBndList();}

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf30000.ipt_isuNm_onkeydown' }); }
};

/**
 * @method
 * @name ipt_isuNm_onblur
 * @description ipt_isuNm 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_isuNm_onblur = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.str.replaceAll(selfVar);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf30000.ipt_isuNm_onblur' }); }
};

/**
 * @method
 * @name grd_result_oncellclick
 * @description grd_result 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_result */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.searchBndSpec(r["stdCd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchStripBndList
 * @description search Strip Bnd List 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchStripBndList = async function (action) {
    const sbmOptions = {
        id: "tx_fn_searchStripBndList",
        method: "post",
        action: action ?? "/strip/strip.do?method=searchStripBndList",
        ref: "dma_searchStripBndListReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_searchBndSpec
 * @description search Bnd Spec 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchBndSpec = async function (action) {
    const sbmOptions = {
        id: "tx_fn_searchBndSpec",
        method: "post",
        action: action ?? "/strip/strip.do?method=searchBndSpecByNew",
        ref: "dma_searchBndSpecReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name searchStripBndList
 * @description search Strip Bnd List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchStripBndList = async function () {
    await scwin.tx_fn_searchStripBndList('/strip/strip.do?method=searchStripBndList');
};

/**
 * @method
 * @name searchBndSpec
 * @description search Bnd Spec 처리
 * @param {String} stdCd stdCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchBndSpec = async function (stdCd) {
    let action;
    $c.util.getComponent("dma_searchStripBndListReq").set("stdCd", stdCd);
    const bndMktactTpCd = $c.util.getComponent("dma_searchStripBndListReq").get("bndMktactTpCd");
    if (bndMktactTpCd === "401") {
    } else {
        action = '/strip/strip.do?method=searchBndSpecByAddMerge';
    }
    await scwin.tx_fn_searchBndSpec(action);
};

/**
 * @method
 * @name krxpage_pagenavigator_79_onclick
 * @description krxpage_pagenavigator_79 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_79_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_searchStripBndListReq').set('pageIndex', pi);
        await scwin.searchStripBndList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldbnf30000.krxpage_pagenavigator_79_onclick" });
    }
};
